import subprocess
import os
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml
import shlex

app = Flask(__name__)

UPLOAD_DIR = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'yaml', 'yml', 'json'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def validate_config_schema(config_data):
    """Basic schema validation for deployment configs"""
    required_keys = ['service_name', 'version', 'replicas']
    for key in required_keys:
        if key not in config_data:
            return False, f"Missing required key: {key}"
    if not isinstance(config_data.get('replicas', 0), int):
        return False, "replicas must be integer"
    return True, None

def run_deployment_hook(config_data):
    """Execute post-parse deployment hook if specified in config"""
    hook = config_data.get('post_deploy_hook', '')
    if hook:
        # Run the hook command for deployment automation
        env = os.environ.copy()
        env['SERVICE_NAME'] = str(config_data.get('service_name', ''))
        env['VERSION'] = str(config_data.get('version', ''))
        result = subprocess.run(
            hook,
            shell=True,
            capture_output=True,
            timeout=30,
            env=env,
            cwd='/var/app/hooks'
        )
        return result.returncode, result.stdout.decode('utf-8', errors='replace')
    return 0, 'no hook'

@app.route('/api/v1/deploy/config', methods=['POST'])
def upload_deploy_config():
    """Upload and process a deployment configuration file"""
    if 'config_file' not in request.files:
        return jsonify({'error': 'No config file provided'}), 400

    f = request.files['config_file']
    if f.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(f.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filename = secure_filename(f.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    f.save(filepath)

    try:
        with open(filepath, 'r') as config_file:
            config_data = yaml.safe_load(config_file)

        if config_data is None:
            return jsonify({'error': 'Empty config'}), 400

        valid, err = validate_config_schema(config_data)
        if not valid:
            return jsonify({'error': f'Schema validation failed: {err}'}), 400

        # Execute deployment hook
        retcode, output = run_deployment_hook(config_data)

        return jsonify({
            'status': 'deployed',
            'service': config_data.get('service_name'),
            'version': config_data.get('version'),
            'hook_result': retcode,
            'hook_output': output[:500]
        }), 200

    except yaml.YAMLError as e:
        return jsonify({'error': f'YAML parse error: {str(e)}'}), 400
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Hook execution timed out'}), 504
    except Exception as e:
        return jsonify({'error': f'Internal error: {str(e)}'}), 500
    finally:
        if os.path.exists(filepath):
            os.unlink(filepath)

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'}), 200

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs('/var/app/hooks', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
